import{c as s,Q as t,j as i,m as a}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/live-tv.md","filePath":"advanced/live-tv.md"}'),n={name:"advanced/live-tv.md"};function r(o,e,l,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.16 <strong>Since:</strong> 0.18.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Live TV lets you watch and record broadcast, cable, and IPTV channels through Phlix. You connect a tuner (HDHomeRun over the network, a USB DVB-T stick on Linux, or an IPTV M3U playlist), configure guide data (Schedules Direct or XMLTV), and you&#39;re ready to watch live TV or schedule recordings. Setup takes 10–30 minutes depending on tuner type and guide data source. Once configured, Live TV appears alongside your regular media library.</p><hr><h2 id="_1-tuner-types-—-which-one-to-use" tabindex="-1">1. Tuner Types — Which One to Use <a class="header-anchor" href="#_1-tuner-types-—-which-one-to-use" aria-label="Permalink to &quot;1. Tuner Types — Which One to Use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tuner</th><th>Connection</th><th>Platforms</th><th>Channels</th><th>Notes</th></tr></thead><tbody><tr><td>HDHomeRun</td><td>Network (Ethernet/WiFi)</td><td>Any</td><td>ATSC/DVB-C/T</td><td>Zero-config discovery on LAN</td></tr><tr><td>USB DVB-T/T2</td><td>USB on server</td><td>Linux only</td><td>DVB-T/T2</td><td>Kernel drivers required</td></tr><tr><td>IPTV / M3U</td><td>Internet/IPTV</td><td>Any</td><td>Varies</td><td>Playlist from ISP or IPTV provider</td></tr></tbody></table><p><strong>Recommendation:</strong> HDHomeRun for most users (simplest), IPTV for cord-cutters without an antenna, DVB-T for Linux-only servers with antenna access.</p><hr><h2 id="_2-setting-up-an-hdhomerun-tuner" tabindex="-1">2. Setting Up an HDHomeRun Tuner <a class="header-anchor" href="#_2-setting-up-an-hdhomerun-tuner" aria-label="Permalink to &quot;2. Setting Up an HDHomeRun Tuner&quot;">​</a></h2><h3 id="step-by-step" tabindex="-1">Step-by-step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step-by-step&quot;">​</a></h3><ol><li>Connect the HDHomeRun device to your network (wired recommended for reliability).</li><li>Discover the device IP address:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Auto-discover HDHomeRun devices on the LAN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdhomerun_config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example output:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hdhr: 192.168.1.100 / tuners: 2</span></span></code></pre></div><ol start="3"><li>Verify the channel lineup is detected:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Replace DEVICE_ID with your HDHomeRun device ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdhomerun_config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DEVICE_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lineup/status</span></span></code></pre></div><p>You should see a list of channels with numbers and names. If the list is empty, the HDHomeRun may not have found antenna/cable channels — check your antenna placement or cable signal.</p><ol start="4"><li>In the Phlix web UI: go to <strong>Settings → Live TV → Add Tuner → HDHomeRun</strong>.</li><li>The device IP is auto-detected if it is on the same LAN. Select it and confirm.</li><li>Phlix scans and imports all detected channels.</li></ol><h3 id="tuner-status-and-concurrent-streams" tabindex="-1">Tuner status and concurrent streams <a class="header-anchor" href="#tuner-status-and-concurrent-streams" aria-label="Permalink to &quot;Tuner status and concurrent streams&quot;">​</a></h3><p>Each HDHomeRun model specifies a maximum number of simultaneous streams (commonly 2 or 4). The Live TV section of the UI shows each tuner and its current status (<strong>idle / streaming / recording</strong>). You cannot exceed the per-tuner stream limit — a second stream request when all tuners are busy returns an error.</p><hr><h2 id="_3-setting-up-a-usb-dvb-t-tuner-linux" tabindex="-1">3. Setting Up a USB DVB-T Tuner (Linux) <a class="header-anchor" href="#_3-setting-up-a-usb-dvb-t-tuner-linux" aria-label="Permalink to &quot;3. Setting Up a USB DVB-T Tuner (Linux)&quot;">​</a></h2><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li>Linux server with a kernel supporting DVB-T/T2 (most modern kernels)</li><li>A supported USB DVB-T/T2 stick (e.g., RTL-SDR, Astro DMW, Hauppauge WinTV)</li><li>Antenna connected to the tuner</li></ul><h3 id="step-by-step-1" tabindex="-1">Step-by-step <a class="header-anchor" href="#step-by-step-1" aria-label="Permalink to &quot;Step-by-step&quot;">​</a></h3><ol><li>Plug the USB tuner into the server. Check <code>dmesg</code> for recognition:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dmesg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dvb</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Expected: &quot;DVB: registering adapter 0/0&quot; etc.</span></span></code></pre></div><ol start="2"><li>Install the required firmware (varies by tuner — check the device docs):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example for RTL-SDR:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> librtlsdr0</span></span></code></pre></div><ol start="3"><li>In Phlix: go to <strong>Settings → Live TV → Add Tuner → DVB-T</strong>.</li><li>Phlix scans the available frequency range and imports discovered channels.</li><li>If no channels are found: check antenna placement, try outdoors, or use an amplified antenna.</li></ol><p><strong>Linux-only note:</strong> DVB-T tuners require the server to be Linux. If your Phlix server runs in Docker on a NAS, USB passthrough must be correctly configured for the container to access the device.</p><hr><h2 id="_4-setting-up-iptv-m3u" tabindex="-1">4. Setting Up IPTV / M3U <a class="header-anchor" href="#_4-setting-up-iptv-m3u" aria-label="Permalink to &quot;4. Setting Up IPTV / M3U&quot;">​</a></h2><h3 id="when-to-use-iptv" tabindex="-1">When to use IPTV <a class="header-anchor" href="#when-to-use-iptv" aria-label="Permalink to &quot;When to use IPTV&quot;">​</a></h3><p>When you have an IPTV subscription from an ISP or third-party provider, or when you use a public IPTV service that provides an M3U playlist.</p><h3 id="step-by-step-2" tabindex="-1">Step-by-step <a class="header-anchor" href="#step-by-step-2" aria-label="Permalink to &quot;Step-by-step&quot;">​</a></h3><ol><li>Get the M3U playlist file from your IPTV provider (usually a <code>.m3u</code> or <code>.m3u8</code> URL or file).</li><li>In Phlix: go to <strong>Settings → Live TV → Add IPTV Tuner</strong>.</li><li>Upload the <code>.m3u</code> file or paste the M3U URL.</li><li>Phlix imports the channel list from the playlist.</li><li>Optional: upload XMLTV guide data (see §5 below).</li></ol><p><strong>M3U format:</strong> Phlix reads <code>#EXTINF</code> lines for channel names and channel numbers. The order in the M3U determines the channel numbering unless overridden.</p><hr><h2 id="_5-setting-up-the-electronic-program-guide-epg" tabindex="-1">5. Setting Up the Electronic Program Guide (EPG) <a class="header-anchor" href="#_5-setting-up-the-electronic-program-guide-epg" aria-label="Permalink to &quot;5. Setting Up the Electronic Program Guide (EPG)&quot;">​</a></h2><p>Live TV is significantly more useful with guide data (EPG) showing program listings and schedules. Phlix supports two sources: <strong>Schedules Direct</strong> (recommended) and <strong>XMLTV</strong> (self-hosted).</p><h3 id="_5a-schedules-direct-recommended" tabindex="-1">5a. Schedules Direct (Recommended) <a class="header-anchor" href="#_5a-schedules-direct-recommended" aria-label="Permalink to &quot;5a. Schedules Direct (Recommended)&quot;">​</a></h3><p><strong>Account setup:</strong></p><ol><li>Go to <a href="https://www.schedulesdirect.org" target="_blank" rel="noreferrer">schedulesdirect.org</a> and create an account (~$25/year).</li><li>Log in and select your lineup (antenna channels by ZIP/postal code or your IPTV provider&#39;s channel lineup).</li><li>Note your username and password for the next step.</li></ol><p><strong>In Phlix:</strong></p><ol><li>Go to <strong>Settings → Live TV → EPG Source → Schedules Direct</strong>.</li><li>Enter your Schedules Direct username and password.</li><li>Phlix connects and syncs your channel lineup.</li><li>Initial sync downloads ~14 days of guide data and may take a few minutes.</li><li>Guide data refreshes automatically every night. To force an immediate refresh, click <strong>Refresh Guide</strong> in the Live TV settings.</li></ol><p><strong>What you get:</strong> Program titles, descriptions, start/end times, categories, and original air dates for each channel. This data powers the program guide in the UI, upcoming program listings, and DVR series rule matching.</p><h3 id="_5b-xmltv-import-self-hosted-free" tabindex="-1">5b. XMLTV Import (Self-Hosted / Free) <a class="header-anchor" href="#_5b-xmltv-import-self-hosted-free" aria-label="Permalink to &quot;5b. XMLTV Import (Self-Hosted / Free)&quot;">​</a></h3><p>If you prefer not to pay for Schedules Direct, you can use free XMLTV data from <a href="https://www.xmltv.org" target="_blank" rel="noreferrer">xmltv.org</a> or a similar source. Free XMLTV data is often less complete and may have stale or missing entries for some channels.</p><p><strong>Step-by-step:</strong></p><ol><li>Download an XMLTV schedule for your region (e.g., from xmltv.org).</li><li>In Phlix: go to <strong>Settings → Live TV → EPG Source → XMLTV Import</strong>.</li><li>Upload the <code>.xml</code> or <code>.xml.gz</code> file.</li><li>Phlix parses and imports the guide data.</li><li>Re-upload periodically (or script it) to keep the guide current.</li></ol><hr><h2 id="_6-dvr-scheduling-basics" tabindex="-1">6. DVR Scheduling Basics <a class="header-anchor" href="#_6-dvr-scheduling-basics" aria-label="Permalink to &quot;6. DVR Scheduling Basics&quot;">​</a></h2><p>Once your tuners and guide data are configured, you can schedule recordings.</p><h3 id="series-rules" tabindex="-1">Series Rules <a class="header-anchor" href="#series-rules" aria-label="Permalink to &quot;Series Rules&quot;">​</a></h3><p>When you record a show from the guide, Phlix asks whether to create a <strong>series rule</strong>:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td>Record all episodes</td><td>Records every future episode of this show</td></tr><tr><td>New episodes only</td><td>Skips reruns; only records episodes flagged as new</td></tr><tr><td>Specific timeslot</td><td>Records only episodes that air in the chosen time slot</td></tr></tbody></table><p>Series rules appear in <strong>Settings → Live TV → Recording Rules</strong> where you can edit or delete them.</p><h3 id="conflict-resolution" tabindex="-1">Conflict Resolution <a class="header-anchor" href="#conflict-resolution" aria-label="Permalink to &quot;Conflict Resolution&quot;">​</a></h3><p>When two shows are scheduled to record at the same time:</p><ol><li><strong>Both tuners free</strong> — both recordings start normally.</li><li><strong>One tuner busy, one free</strong> — the free tuner records the higher-priority show; the other is marked as conflict.</li><li><strong>Both tuners busy</strong> — one show is recorded; the other is marked as conflict and you are notified.</li></ol><p><strong>Conflict resolution preference:</strong> In <strong>Settings → Live TV → DVR</strong>, you can set whether Phlix prefers to keep existing recordings or prioritize new episodes when resolving conflicts.</p><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><p>Recordings are stored in the path configured in <strong>Settings → Live TV → Storage</strong>. This can be a dedicated folder (e.g., <code>/var/recordings</code>) or a subfolder of an existing media library.</p><p>Storage usage is shown in <strong>Settings → Live TV → Storage</strong> with total / used / free bytes.</p><p><strong>Post-recording:</strong> After a recording completes, Comskip runs automatically if enabled (see <a href="./live-tv-comskip.html">Live TV Comskip</a>) to detect and flag commercials.</p><hr><h2 id="_7-what-can-go-wrong" tabindex="-1">7. What Can Go Wrong <a class="header-anchor" href="#_7-what-can-go-wrong" aria-label="Permalink to &quot;7. What Can Go Wrong&quot;">​</a></h2><h3 id="failure-1-hdhomerun-not-discovered-udp-port-65001-blocked" tabindex="-1">Failure 1: HDHomeRun Not Discovered (UDP Port 65001 Blocked) <a class="header-anchor" href="#failure-1-hdhomerun-not-discovered-udp-port-65001-blocked" aria-label="Permalink to &quot;Failure 1: HDHomeRun Not Discovered (UDP Port 65001 Blocked)&quot;">​</a></h3><p><strong>Symptom:</strong> HDHomeRun tuner is connected to the network but does not appear in Phlix during setup.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hdhomerun_config uses UDP port 65001 for discovery</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -zvu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 65001</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or use the discovery command (broadcasts on UDP 65001)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdhomerun_config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><p><strong>Fix:</strong> Open UDP port 65001 on your server firewall, router firewall, or VPN. Alternatively, manually enter the HDHomeRun IP address during setup instead of using auto-discovery. Find the IP via your router&#39;s device list or by checking the HDHomeRun&#39;s built-in web interface at <code>http://&lt;hdhomerun-ip&gt;</code>.</p><hr><h3 id="failure-2-epg-guide-data-shows-wrong-channels-m3u-xmltv-mismatch" tabindex="-1">Failure 2: EPG Guide Data Shows Wrong Channels (M3U + XMLTV Mismatch) <a class="header-anchor" href="#failure-2-epg-guide-data-shows-wrong-channels-m3u-xmltv-mismatch" aria-label="Permalink to &quot;Failure 2: EPG Guide Data Shows Wrong Channels (M3U + XMLTV Mismatch)&quot;">​</a></h3><p><strong>Symptom:</strong> The program guide appears but channel numbers or names don&#39;t match the actual channels in the M3U playlist.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the first few entries of your M3U playlist — note the #EXTINF channel numbers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/playlist.m3u</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the corresponding channel IDs in your XMLTV file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;channel&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/guide.xml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The M3U #EXTINF index order should match the XMLTV channel IDs</span></span></code></pre></div><p><strong>Fix:</strong> The M3U and XMLTV files must have matching channel references. Re-export the M3U or XMLTV with matching channel identifiers, or switch to Schedules Direct which maintains its own channel map and avoids this mismatch entirely.</p><hr><h3 id="failure-3-dvr-storage-drive-fills-up" tabindex="-1">Failure 3: DVR Storage Drive Fills Up <a class="header-anchor" href="#failure-3-dvr-storage-drive-fills-up" aria-label="Permalink to &quot;Failure 3: DVR Storage Drive Fills Up&quot;">​</a></h3><p><strong>Symptom:</strong> Recordings stop mid-recording or fail to start. The Live TV UI shows a storage error.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check recording storage path usage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">df</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/recordings</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List recording file sizes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/recordings/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span></code></pre></div><p><strong>Fix:</strong> Free up space by deleting completed recordings you no longer need, changing the storage path to a larger drive (<strong>Settings → Live TV → Storage</strong>), or setting a maximum storage limit. Enable <strong>auto-delete</strong> to remove old recordings when space is low.</p><hr><h3 id="failure-4-recording-missed-due-to-tuner-conflict" tabindex="-1">Failure 4: Recording Missed Due to Tuner Conflict <a class="header-anchor" href="#failure-4-recording-missed-due-to-tuner-conflict" aria-label="Permalink to &quot;Failure 4: Recording Missed Due to Tuner Conflict&quot;">​</a></h3><p><strong>Symptom:</strong> A scheduled recording did not happen. The recording shows as &quot;Missed&quot; or &quot;Conflict&quot; in the UI. The tuner was busy with another show at the same time.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the Live TV tuner status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:32400/api/v1/livetv/tuners</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Look for a tuner that was busy (status: recording) during the missed show&#39;s time slot</span></span></code></pre></div><p><strong>Fix:</strong> Conflict resolution follows the priority set in <strong>Settings → Live TV → DVR</strong>. To avoid this: add a second tuner, adjust series rules to avoid overlapping timeslots, set conflict preference to &quot;prioritize new episodes,&quot; or check the <strong>Upcoming Recordings</strong> list regularly for conflicts.</p><hr><h2 id="_8-next-steps" tabindex="-1">8. Next Steps <a class="header-anchor" href="#_8-next-steps" aria-label="Permalink to &quot;8. Next Steps&quot;">​</a></h2><ul><li><a href="./live-tv-comskip.html">Live TV Comskip</a> — configure automatic commercial detection and skipping in recordings</li><li><a href="./../clients/dlna.html">DLNA / Play To</a> — stream live TV or recordings to DLNA-enabled devices</li><li><a href="./../hub/remote-access.html">Remote Access / Hub</a> — access Live TV from outside your home network</li><li><a href="./live-tv-recordings.html">Recording Rules</a> — managing and editing scheduled recordings</li></ul>`,92)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
